/**
 * The six illustrations of the demonstration wiki, written out as WebP in base64.
 *
 * The repository ships no image file, and an image of the wiki is a data url or an
 * absolute address, so the demonstration carries its plates in the code rather
 * than asking a placeholder service for them on every view: it then works without
 * a network, like the rest of the wiki, and stores what it shows. Each was reduced
 * to 640 pixels wide and encoded at a quality of 0.35, as low as a plate stays
 * legible at the width of the infobox, so the six weigh about a hundred kilobytes
 * of the five megabytes `localStorage` grants. They are monochrome, so they read as
 * plates of an archive rather than as holiday photographs.
 *
 * Each string is cut into lines of a hundred characters joined back together, so
 * the module keeps the column limit of the codebase. It is only imported by
 * `demo.ts`, itself imported on demand, so a reader who never asks for the
 * demonstration never downloads it.
 *
 * @author Claude
 */

/**
 * Joins the lines of one encoded image back into its data url.
 *
 * @param parts The base64 payload, cut into lines.
 * @returns The data url of the image.
 * @author Claude
 */
const webp = ( parts: readonly string[] ): string => `data:image/webp;base64,${ parts.join( "" ) }`;

